let practiceRun=null,usageBattle=null,practiceReturn=null,usageLimit=60,usageDetailReturn=false,playSyncBusy=false,playSyncTimer=null,playSyncStatus='保存状況を確認中…',practiceDeckDraft=null,practiceDeckSelected=0,practiceDeckLimit=60,practiceDeckSource='list',practiceDeckReturn=null,practiceDeckShooter=null,practiceDeckChallenge=null,practiceDeckEquipment={},practiceDraftFormation=null;
function practiceChallenge(){return practiceRun?.challenge||KanjiPlayRecords.get(practiceRun?.id);}
const practiceEl=id=>document.getElementById(id),isPractice=()=>battleMode==='practice'&&!!practiceRun;
