 const c=practiceChallenge();practiceEnemies().forEach((item,n)=>{const p=c.points[n],body=KanjiTraits.createBody(item,center.x+p.x*r,center.y-p.y*r,r/184,{},Math.PI-p.angle);body.gameData={...item,isPlayer:false};KanjiPieceArt.draw(cx,body,0,true);});
