window.initializePlayRecords=()=>{KanjiPlayRecords.initializeDeviceUsage(gameState);setTimeout(syncPlayProgress,300);};
let playSyncFailures=0,playSyncAutomatic=false;
const playSyncBlocked=new Map();
function pendingPlayEvents(){return gameState.playPending.filter(e=>playSyncBlocked.get(e.id)!==JSON.stringify(e));}
function schedulePlaySync(ms){clearTimeout(playSyncTimer);if(!document.hidden)playSyncTimer=setTimeout(()=>{playSyncAutomatic=true;syncPlayProgress();},ms);}
window.queuePlaySync=()=>schedulePlaySync(500);
window.syncPlayProgress=async()=>{
 if(playSyncBusy)return;const automatic=playSyncAutomatic;playSyncAutomatic=false;if(!automatic)playSyncBlocked.clear();clearTimeout(playSyncTimer);playSyncBusy=true;let retryDelay=0;
 try{
  if(typeof syncCpuSkillBestRecords==='function')await syncCpuSkillBestRecords();
  const initial=await playerApi('/api/play-progress');
  if(gameState.playChallengeDeviceScopeVersion!==1){gameState.playChallengeSharedArchive=structuredClone(gameState.playProgress?.challenges||{});gameState.playChallengeDeviceScopeVersion=1;}if(gameState.playUsageOwner!==initial.usageOwner)playSyncBlocked.clear();KanjiPlayRecords.bindDeviceUsage(gameState,initial.usageOwner,initial.progress);saveState();
  const events=pendingPlayEvents().slice(0,10);if(events.some(e=>KanjiCpuSkill.get(e.challenge)))await ensurePlayerProfile();const retireLegacy=gameState.playLegacyRetiredOwner!==gameState.playUsageOwner;const result=events.length||retireLegacy?await playerApi('/api/play-progress','POST',{events,usageOwner:gameState.playUsageOwner,retireLegacy,partial:true}):initial;if(retireLegacy)gameState.playLegacyRetiredOwner=gameState.playUsageOwner;
  if(result.usageOwner!==gameState.playUsageOwner)throw Error('usage-owner-changed');
  if(!KanjiPlayRecords.validProgress(result.progress,c=>KANJI_DATABASE.some(i=>i.char===c)))throw Error('記録を読み込めませんでした。');
  const accepted=new Set(result.accepted||[]);for(const id of accepted)playSyncBlocked.delete(id);for(const rejection of result.rejected||[]){const event=events.find(e=>e.id===rejection.id);if(event)playSyncBlocked.set(event.id,JSON.stringify(event));}
  gameState.playPending=gameState.playPending.filter(e=>!accepted.has(e.id));gameState.playProgress=result.progress;if(typeof acceptCpuSkillRecords==='function')acceptCpuSkillRecords(result.cpuSkillRecords);for(const e of gameState.playPending)KanjiPlayRecords.apply(gameState.playProgress,e);
  for(const [id,v]of Object.entries(result.progress.challenges))if(v.clears&&!gameState.practiceRewardClaims.includes(id))gameState.practiceRewardClaims.push(id);
  if(events.some(e=>e.cpuSkill)&&typeof loadLeaderboard==='function'&&practiceEl('leaderboard-rule').value==='cpu-skill')loadLeaderboard();playSyncFailures=0;playSyncStatus=gameState.playPending.length?(pendingPlayEvents().length?'残りの実績を保存中…':'確認が必要な実績を端末に保管しています。「保存状況を更新」で再確認できます。'):'この端末の使用実績を保存済み';saveState();if(pendingPlayEvents().length)retryDelay=500;
 }catch(e){
  if([400,403,404,409,413,422].includes(e.status)){for(const event of pendingPlayEvents().slice(0,10))playSyncBlocked.set(event.id,JSON.stringify(event));playSyncStatus='実績を端末に保管しています。接続先・記録を確認して「保存状況を更新」を押してください。';}
  else{playSyncFailures++;retryDelay=Math.max(e.retryAfter||0,KanjiNetwork.delay(15000,playSyncFailures-1,300000));playSyncStatus=e.status===401?'この端末に保存中。通信が戻ると、このプレイヤーの実績をサーバーにも保存します。':'通信が戻ったら実績を再保存します。端末の記録は残っています。';}
 }finally{playSyncBusy=false;refreshPracticeViews();if(pendingPlayEvents().length&&retryDelay)schedulePlaySync(retryDelay);}
};
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(playSyncTimer);else if(pendingPlayEvents().length)schedulePlaySync(KanjiNetwork.delay(500,1,2000));});
window.addEventListener('online',()=>{if(pendingPlayEvents().length)schedulePlaySync(KanjiNetwork.delay(500,1,2000));});

function acceptPlayEvent(event){const before=KanjiHonors.fromState(gameState,KANJI_DATABASE);if(!event||gameState.playPending.some(e=>e.id===event.id))return;KanjiPlayRecords.apply(gameState.playProgress,event);gameState.playPending.push(event);saveState();const unlocked=KanjiHonors.catalogue.filter(i=>i.id.startsWith('usage-')&&!KanjiHonors.canUse(i.id,before)&&KanjiHonors.canUse(i.id,gameState.iconProgress));if(unlocked.length)showToast('使用実績の枠を解放：'+unlocked.map(i=>i.name).join('・'));queuePlaySync();refreshPracticeViews();}
let medalBattle=null;
function settleBattleMedals(run,winner){const before=gameState.iconProgress||{};KanjiMedals.finish(gameState,run,winner);const after=KanjiHonors.fromState(gameState,KANJI_DATABASE),unlocked=KanjiMedals.badges.filter(b=>(before[b.key]||0)<b.value&&(after[b.key]||0)>=b.value);if(unlocked.length)setTimeout(()=>showToast('勲章を解放：'+unlocked.map(b=>b.name).join('・')),100);}
window.beginUsageBattle=team=>{usageBattle=KanjiPlayRecords.createUsage(playerRandomId(),team);medalBattle=KanjiMedals.start(usageBattle.id,team,{eligible:!(isPractice()&&practiceRun.kind==='cpu-skill')&&team.every(i=>gameState.inventory.some(owned=>owned.instanceId===i.instanceId)),friendCode:battleMode==='friend-cpu'?friendCpuChallenge.code:null});if(isPractice()&&practiceRun.challenge?.season)usageBattle.cpuSkill={season:practiceRun.challenge.season,version:3,killTurns:[]};};
window.recordUsageFinish=winner=>{const event=KanjiPlayRecords.event(usageBattle,winner,playerBodies.filter(b=>!b.gameData.isOut).map(b=>b.gameData.instanceId),isPractice()?practiceRun.id:null);if(event)settleBattleMedals(medalBattle,winner);acceptPlayEvent(event);return event;};
window.recordFriendUsage=room=>{
 if(!room.state?.finished||!room.state.usage)return;const id=`room_${room.code}_${room.round}_${room.side}`;if(gameState.playPending.some(e=>e.id===id)||gameState.lastUsageRoom===id)return;gameState.lastUsageRoom=id;
 const team=(room.side?room.guest:room.host).items,run=KanjiPlayRecords.createUsage(id,team.map((i,n)=>({...i,instanceId:'piece_'+n})));run.items.forEach((i,n)=>Object.assign(i,room.state.usage[room.side][n]));run.shots=run.items.reduce((sum,i)=>sum+i.shots,0);const medals=KanjiMedals.start(id,team,{eligible:team.every(i=>gameState.inventory.some(v=>v.char===i.char))});if(room.state.medals){medals.kills=room.state.medals.kills[room.side];medals.abilities=room.state.medals.abilities[room.side];medals.comeback=room.state.medals.comeback[room.side];}settleBattleMedals(medals,room.state.winner===room.side);const survived=room.state.pieces.filter(p=>Math.floor(p.key/3)===room.side&&!p.data.isOut).map(p=>'piece_'+p.key%3);acceptPlayEvent(KanjiPlayRecords.event(run,room.state.winner===null?null:room.state.winner===room.side,survived));
};
