window.endPracticeChallenge=()=>{if(practiceRun?.kind==='cpu-skill'){endCpuSkillChallenge();return;}const kind=practiceRun?.kind||'condition',promotion=kind.startsWith('promotion-');practiceRun=null;battleMode='classic';practiceEl('modal-result').classList.add('hidden');resetBattle();switchTab(promotion?'rank':'play');if(promotion){setRecordsView('rank');renderPromotionTrials();}else openPracticeChallenges(kind);};
