function renderPracticeTeamPreview(team){
 const box=practiceEl('practice-team-preview');box.replaceChildren();box.append(practiceNode('h3','', '挑戦前の編成'));const slots=practiceNode('div','practice-deck-slots');
 for(let n=0;n<3;n++){const item=team[n],b=practiceNode('button','practice-team-slot');b.type='button';b.dataset.practicePreviewSlot=String(n);b.setAttribute('aria-label',`枠${n+1} ${item?.char||'空き'}の編成を変更`);b.append(practiceNode('span','',`枠${n+1}`),practiceNode('strong','kanji-font',item?.char||'＋'),practiceNode('small','',item?`所持Lv.${item.level}・${ATTR_INFO[item.attr].name}属性`:'文字を選ぶ'));b.onclick=()=>openPracticeDeck('list',n);slots.append(b);}box.append(slots,practiceNode('p','practice-note','出撃用デッキを反映しています。文字の変更・お気に入りの呼び出しは出撃デッキにも反映されます。'));
}
window.openPracticeDeck=(source='list',selected=0)=>{
 if(source==='battle'&&(!isPractice()||practiceRun.started||!soloBattlePending))return;
 practiceDeckChallenge=source==='battle'?practiceRun?.id:null;practiceEl('practice-deck-recommend-status').textContent='';practiceDeckDraft=gameState.deck.slice();practiceDeckEquipment={};practiceDraftFormation=KanjiFormation.copy(getActiveFormation());practiceDeckShooter=gameState.practiceShooter||practiceDeckDraft[0];practiceDeckSelected=selected;practiceDeckLimit=60;practiceDeckSource=source;practiceEl('practice-deck-title').textContent=source==='deployment'?'出撃用デッキの編成':'チャレンジ用の編成';practiceDeckReturn=document.activeElement;resetPracticePicker(false);renderPracticeDraftFavorites();practiceEl('practice-draft-favorite-status').textContent='出撃用デッキを反映しています。編成を確定するまで変更は保存されません。';pausePlayerOverlay();practiceEl('modal-practice-deck').classList.remove('hidden');practiceEl('modal-practice-deck').querySelector('.ui-deck-scroll').scrollTop=0;renderPracticeDeck();practiceEl('modal-practice-deck').querySelector('.editor-title button').focus();
};
window.closePracticeDeck=()=>{practiceDeckDraft=null;practiceEl('modal-practice-deck').classList.add('hidden');resumePlayerEngine();if(practiceDeckReturn?.isConnected)practiceDeckReturn.focus();};
window.selectPracticeDeckItem=id=>{
 if(!practiceDeckDraft||!gameState.inventory.some(i=>i.instanceId===id))return;const previous=practiceDeckDraft[practiceDeckSelected],existing=practiceDeckDraft.indexOf(id);if(existing>=0)practiceDeckDraft[existing]=previous;practiceDeckDraft[practiceDeckSelected]=id;renderPracticeDeck();
};
window.renderPracticeDeck=reset=>{
 if(!practiceDeckDraft)return;if(reset)practiceDeckLimit=60;const slots=practiceEl('practice-deck-slots');slots.replaceChildren();
 for(let n=0;n<3;n++){const item=gameState.inventory.find(i=>i.instanceId===practiceDeckDraft[n]),b=practiceNode('button','practice-team-slot');b.type='button';b.dataset.practiceDeckSlot=String(n);b.setAttribute('aria-pressed',String(practiceDeckSelected===n));b.append(practiceNode('span','',`枠${n+1}`),practiceNode('strong','kanji-font',item?.char||'＋'),practiceNode('small','',item?`${ATTR_INFO[item.attr].name}・ルビ${(practiceDeckEquipment[item.instanceId]||getEquippedReadings(item)).length}個`:'未編成'));b.onclick=()=>{practiceDeckSelected=n;renderPracticeDeck();};slots.append(b);}
 const items=KanjiPracticePicker.filter(gameState.inventory,{query:practiceEl('practice-deck-search').value,jis:practiceEl('practice-filter-jis').value,attr:practiceEl('practice-filter-attr').value,ability:practiceEl('practice-filter-ability').value,sort:practiceEl('practice-filter-sort').value},getRealReadings,i=>KanjiReadAbilities.resolveAll(i,window.KANJI_READING_ABILITIES),getKanjiStats,i=>getUnlockedReadings(i).length,KanjiTurnOrder.count),box=practiceEl('practice-deck-picker');box.replaceChildren();
 for(const item of items.slice(0,practiceDeckLimit)){const b=practiceNode('button','practice-owned-choice');b.type='button';b.dataset.practiceOwned=item.instanceId;b.setAttribute('aria-label',`${item.char}を枠${practiceDeckSelected+1}に編成`);b.setAttribute('aria-pressed',String(practiceDeckDraft.includes(item.instanceId)));b.append(practiceNode('strong','kanji-font',item.char),practiceNode('span','',`${getCharacterTypeLabel(item)}・${ATTR_INFO[item.attr].name}`),practiceNode('small','',`Lv.${item.level}・ルビ ${getEquippedReadings(item).length}個`));b.onclick=()=>selectPracticeDeckItem(item.instanceId);box.append(b);}
 if(!items.length)box.append(practiceNode('p','practice-note','該当する所持文字がありません。'));practiceEl('practice-deck-count').textContent=`所持${items.length}体・${Math.min(items.length,practiceDeckLimit)}体を表示`;
 const team=practiceDeckDraft.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean);practiceEl('btn-practice-deck-save').disabled=!team.length;practiceEl('btn-practice-deck-more').hidden=items.length<=practiceDeckLimit;
 const challenge=KanjiPlayRecords.get(practiceDeckChallenge);practiceEl('btn-practice-deck-recommend').hidden=!challenge||!['condition','promotion-mission'].includes(challenge.kind);const oneShot=practiceDeckSource!=='deployment'&&(challenge?challenge.kind==='one-shot':practiceEl('modal-practice').dataset.kind==='one-shot'),shooter=practiceEl('practice-deck-shooter');shooter.replaceChildren();shooter.hidden=!oneShot;if(oneShot){if(!practiceDeckDraft.includes(practiceDeckShooter))practiceDeckShooter=team[0]?.instanceId;shooter.append(practiceNode('p','practice-note','この文字で発射'));for(const item of team){const b=practiceNode('button','inventory-action secondary',item.char);b.type='button';b.dataset.practiceDraftShooter=item.instanceId;b.setAttribute('aria-pressed',String(practiceDeckShooter===item.instanceId));b.onclick=()=>{practiceDeckShooter=item.instanceId;renderPracticeDeck();};shooter.append(b);}}practiceEl('practice-deck-rule').textContent=practiceDeckSource==='deployment'?'枠を選んで文字をタップ。編成を確定すると出撃用デッキに反映します。':challenge?challenge.condition+'。'+(KanjiPlayRecords.condition(challenge.id,team,KanjiTurnOrder.count)||'挑戦条件を満たしています。'):'条件付きチャレンジは3体、一撃チャレンジはこの編成から発射する1体を選びます。';
};
window.showMorePracticeDeck=()=>{practiceDeckLimit+=60;renderPracticeDeck();};
window.savePracticeDeck=()=>{
 if(!practiceDeckDraft)return;for(const id of practiceDeckDraft){const item=gameState.inventory.find(i=>i.instanceId===id),readings=practiceDeckEquipment[id];if(item&&readings){item.equippedReadings=readings.filter(r=>getUnlockedReadings(item).includes(r));item.ruby=item.equippedReadings[0]||'';item.readingEquipped=!!item.ruby;}}gameState.loadedDeckFormation=practiceDraftFormation?KanjiFormation.fit(practiceDeckDraft.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean),practiceDraftFormation).points:null;gameState.deck=practiceDeckDraft.filter(id=>gameState.inventory.some(i=>i.instanceId===id));if(!gameState.deck.length)return;gameState.practiceShooter=gameState.deck.includes(practiceDeckShooter)?practiceDeckShooter:gameState.deck[0];saveState();renderDeckSlots();renderCollection();updateBattleDeckSummary();
 if(isPractice()&&!practiceRun.started){practiceRun.team=KanjiPlayRecords.prepareTeam(practiceRun.id,currentPracticeTeam(),gameState.practiceShooter);practiceRun.formation=practiceRun.kind==='one-shot'?KanjiFormation.fit(practiceRun.team,practiceRun.formation).points:KanjiFormation.copy(getActiveFormation());resetBattle();}
 if(!practiceEl('modal-practice').classList.contains('hidden'))renderPracticeChallenges();closePracticeDeck();renderBattlePreparation();
};
window.backToPracticeChallenges=()=>{if(!isPractice()||!soloBattlePending||practiceRun.started)return;endPracticeChallenge();};

const renderPracticeChallengesBase=renderPracticeChallenges;
renderPracticeChallenges=function(){renderPracticeChallengesBase();renderTrialFavorites();};
function renderTrialFavorites(){const modal=practiceEl('modal-practice');let panel=practiceEl('trial-favorites');if(!panel){panel=practiceNode('section','practice-card');panel.id='trial-favorites';practiceEl('practice-list').before(panel);}panel.hidden=false;if(panel.hidden)return;panel.replaceChildren(practiceNode('h3','','お気に入り編成から選ぶ'));const status=practiceNode('p','');status.id='trial-favorite-status';status.setAttribute('role','status');for(const favorite of gameState.deckFavorites||[]){const button=practiceNode('button','inventory-action secondary',favorite.name+'：'+favorite.items.map(i=>i.char).join('・'));button.type='button';button.dataset.trialFavorite=favorite.slot;button.onclick=()=>{const ok=loadDeckFavorite(favorite.slot),message=practiceEl('deck-favorites-status').textContent;renderPracticeChallenges();practiceEl('trial-favorite-status').textContent=message;if(ok)renderPracticeTeamPreview(currentPracticeTeam());};panel.append(button);}if(!(gameState.deckFavorites||[]).length)panel.append(practiceNode('p','','文字の「お気に入り編成」で登録した編成を選べます。'));const refresh=practiceNode('button','quiet-action','お気に入りを取得');refresh.type='button';refresh.onclick=async()=>{refresh.disabled=true;await initializeDeckFavorites();renderTrialFavorites();practiceEl('trial-favorite-status').textContent=practiceEl('deck-favorites-status').textContent;};panel.append(refresh,status);}

window.resetPracticePicker=(render=true)=>{practiceEl('practice-deck-search').value='';for(const id of ['jis','attr','ability'])practiceEl('practice-filter-'+id).value='';practiceEl('practice-filter-sort').value='owned';const ability=practiceEl('practice-filter-ability');if(ability.options.length===1){for(const a of Object.values(KanjiReadAbilities.abilities)){const option=practiceNode('option','',a.name);option.value=a.id;ability.append(option);}}if(render)renderPracticeDeck(true);};
function renderPracticeDraftFavorites(){const select=practiceEl('practice-draft-favorite'),selected=select.value;select.replaceChildren();for(const f of gameState.deckFavorites||[]){const option=practiceNode('option','',f.name+'：'+f.items.map(i=>i.char).join('・'));option.value=String(f.slot);select.append(option);}if(!select.options.length){const option=practiceNode('option','','登録済みの編成はありません');option.value='';select.append(option);}else if([...select.options].some(o=>o.value===selected))select.value=selected;}
window.refreshPracticeDraftFavorites=async()=>{await initializeDeckFavorites();if(!practiceDeckDraft)return;renderPracticeDraftFavorites();practiceEl('practice-draft-favorite-status').textContent=practiceEl('deck-favorites-status').textContent;};
window.usePracticeDeploymentDeck=()=>{if(!practiceDeckDraft)return;practiceDeckDraft=gameState.deck.slice();practiceDeckEquipment={};practiceDraftFormation=KanjiFormation.copy(getActiveFormation());practiceDeckShooter=practiceDeckDraft[0];renderPracticeDeck();practiceEl('practice-draft-favorite-status').textContent='出撃用デッキを反映しました。';};
window.usePracticeDraftFavorite=()=>{if(!practiceDeckDraft)return;const favorite=(gameState.deckFavorites||[]).find(f=>String(f.slot)===practiceEl('practice-draft-favorite').value);if(!favorite){practiceEl('practice-draft-favorite-status').textContent='文字の編成からお気に入りを登録してください。';return;}const result=KanjiDeckFavorites.resolve(favorite,gameState.inventory,getUnlockedReadings);if(result.missing.length){practiceEl('practice-draft-favorite-status').textContent='所持していない文字：'+result.missing.join('・')+'。編成は変更していません。';return;}practiceDeckDraft=result.items.map(r=>r.item.instanceId);practiceDeckEquipment=Object.fromEntries(result.items.map(r=>[r.item.instanceId,r.equippedReadings.slice()]));practiceDraftFormation=favorite.formation?KanjiFormation.copy(favorite.formation):KanjiFormation.copy(KanjiFormation.defaults);practiceDeckShooter=practiceDeckDraft[0];renderPracticeDeck();practiceEl('practice-draft-favorite-status').textContent='「'+favorite.name+'」を呼び出しました。編成を確定すると反映します。'+(result.rubies.length?'未解放のルビは外しました：'+result.rubies.join('・'):'');};
